import os,pathlib,subprocess,json,pwd,stat,hashlib,shutil
base=pathlib.Path('/srv/projects'); roots=[base/'Vivoapk',base/'jellyfin-server']
def run(args,t=10):
 try:
  p=subprocess.run(args,capture_output=True,text=True,timeout=t,env={**os.environ,'GIT_PAGER':'cat','PAGER':'cat','GIT_OPTIONAL_LOCKS':'0','GIT_TERMINAL_PROMPT':'0'});return p.returncode,p.stdout.strip()
 except (OSError,subprocess.TimeoutExpired):return 125,''
def prop(s,k):return run(['systemctl','show',s,'-p',k,'--value'])[1]
def inventory(p):
 try:
  a=p.stat()
  result={'exists':True,'owner':pwd.getpwuid(a.st_uid).pw_name,'mode':oct(stat.S_IMODE(a.st_mode)),'dirs':[]}
  for x in sorted(p.iterdir()):
   if x.is_symlink():kind='symlink'
   elif x.is_dir():kind='dir'
   else:kind='file'
   if kind=='dir' and x.name not in ('data','config','secrets','credentials','vault','run'):
    try:
     children=[y.name for y in x.iterdir() if y.is_dir() and not y.is_symlink()][:40]
    except OSError:children=[]
   else:children=[]
   if kind=='dir':result['dirs'].append({'name':x.name,'children':children})
  return result
 except OSError as e:return {'readable':False,'error':type(e).__name__}
r={'scope':'Vivoapk and Jellyfin only; no secret contents, no changes','uid':os.geteuid(),'roots':{p.name:inventory(p) for p in roots},'services':{},'git':{},'disk_free_gib':round(shutil.disk_usage(base).free/2**30,2)}
for s in ('jellyfin-pink.service','vivoapk-backend.service','pink-iptv-backend.service','pink-vpn.service','nginx.service','postgresql.service'):
 r['services'][s]={'state':prop(s,'ActiveState'),'unit':prop(s,'LoadState'),'user':prop(s,'User'),'private_network':prop(s,'PrivateNetwork')}
p=roots[0]/'source'
try:
 owner=pwd.getpwuid(p.stat().st_uid).pw_name
 prefix=[] if p.stat().st_uid==os.geteuid() else ['sudo','-n','-u',owner,'--']
 for k,args in {'head':['rev-parse','HEAD'],'branch':['branch','--show-current'],'status':['status','--porcelain','--untracked-files=no'],'worktrees':['worktree','list','--porcelain'],'refs':['for-each-ref','--format=%(refname:short) %(objectname)','refs/heads'],'origin_main':['rev-parse','refs/remotes/origin/main'],'diff_check':['diff','--check']}.items():
  c,v=run(prefix+['git','--no-pager','-C',str(p)]+args)
  r['git'][k]={'exit':c,'output':v[:2500] if k not in ('status','diff_check') else ('clean' if c==0 and not v else 'changes_or_error')}
except OSError as e:r['git']['error']=type(e).__name__
for key,p in [('backend_version',roots[0]/'current'),('plugin',roots[1]/'data/plugins/VivoAPK Mega OTT Auth_0.1.0.0/Jellyfin.Plugin.VivoapkMegaAuth.dll')]:
 try:
  if p.is_symlink():r[key]={'symlink_target':str(p.resolve())}
  elif p.is_file():r[key]={'size':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
  else:r[key]={'exists':p.exists()}
 except OSError as e:r[key]={'error':type(e).__name__}
print(json.dumps(r),flush=True)
